const session = (uid: string, title: string, start: string, end: string, track: string) => [
  'BEGIN:VEVENT',
  `UID:${uid}@devcon.example.com`,
  'DTSTAMP:20261020T120000Z',
  `DTSTART:${start}`,
  `DTEND:${end}`,
  `SUMMARY:${title}`,
  `LOCATION:${track} Hall\\, Northwind Conference Center`,
  `DESCRIPTION:${title}\\, a session at Northwind DevCon.`,
  `URL:https://devcon.example.com/sessions/${uid}`,
  `CATEGORIES:${track},Sessions`,
  'TRANSP:TRANSPARENT',
  'END:VEVENT',
];

/** A conference's schedule: METHOD:PUBLISH, a calendar name, free sessions in overlapping tracks, a URL and CATEGORIES on each. */
